<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Admission Test Rooms</h2><a class="btn btn-primary" href="<?= base_url('school/admission/test-rooms/create') ?>">Create room</a></div><div class="card shadow-sm"><div class="card-body"><table class="table"><thead><tr><th>Room</th><th>School</th><th>Building/Floor</th><th>Layout</th><th>Capacity</th><th></th></tr></thead><tbody><?php foreach($items as $r): ?><tr><td><?= esc($r->room_name) ?> (<?= esc($r->room_no) ?>)</td><td><?= esc($r->school_name) ?></td><td><?= esc(trim(($r->building??'').' '.($r->floor??''))?:'—') ?></td><td><?= $r->rows_count ?> × <?= $r->columns_count ?></td><td><?= $r->capacity ?></td><td><a href="<?= base_url('school/admission/test-rooms/edit/'.$r->token) ?>">Edit</a></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="6" class="text-center text-muted">No rooms configured.</td></tr><?php endif ?></tbody></table></div></div></div>
